    server.tool(name="run_galaxy_tool_and_wait")(run_galaxy_tool_and_wait)
    server.tool(name="run_galaxy_udt_and_wait")(run_galaxy_udt_and_wait)
    server.run(transport="stdio")


if __name__ == "__main__":
